(function(){function init(){document.querySelectorAll('[data-home-team]').forEach(root=>{const track=root.querySelector('[data-home-team-track]'),card=track?.querySelector('.hq-home-team-card');if(!track||!card)return;const step=()=>card.getBoundingClientRect().width+18;root.querySelector('[data-home-team-prev]')?.addEventListener('click',()=>track.scrollBy({left:-step(),behavior:'smooth'}));root.querySelector('[data-home-team-next]')?.addEventListener('click',()=>track.scrollBy({left:step(),behavior:'smooth'}));let timer;const start=()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;clearInterval(timer);timer=setInterval(()=>{if(!document.hidden)track.scrollBy({left:step(),behavior:'smooth'});if(track.scrollLeft+track.clientWidth>=track.scrollWidth-3)track.scrollTo({left:0,behavior:'smooth'});},4800)};root.addEventListener('mouseenter',()=>clearInterval(timer));root.addEventListener('mouseleave',start);root.addEventListener('focusin',()=>clearInterval(timer));root.addEventListener('focusout',start);start()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();